function grid$thpkh(f){
  this.constructor(f);
}
grid$thpkh.prototype = new DirEvent();
grid$thpkh.prototype.afterInit = function(renderType){
  var p = this._dir;
}
grid$thpkh.prototype.beforeButtonGridClick = function(id){
  if (id == 'register') {
    var p = this._dir, g = p.grid(), r = p.curr("r");
    if (r == null || r < 0) return;

    var m = new Memvars(), vc = g.data.val(r, 'id');   
    register(this, vc);
    return false;
  }
  return true
}


function register(o, id) {
  $.invoke('RegisterDepositCode', { id: id }, this, 30000
    , function (result) {
		console.log(result);
      if (result) {
        if(result) $.alert(result);
      }
    }, function (event) {} );
}

